//! Closed BQ062: three standard modes and a persistent investigation marker.
use crate::{engine::RuleResult,model::*,rules::*};
use serde::Serialize;
use std::collections::BTreeSet;
pub(crate) const ID:&str="BQ062";
pub(crate) const KEY:&str="bq062-infusion";
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
const TITLE:&str="信息灌注：选择一个本方场上核心或触手角色";
fn lock_slot()->TargetSlotSpec{target(Zone::Board,EntityKind::CharacterOrHidden,Relation::Any,Range::Anywhere)}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"信息灌注：选择一项",Timing::Standard,vec![],vec![],vec![],None);a.play_only=true;a.modes=vec![Mode{key:"investigate".into(),label:"本方核心或触手永久调查标志，预测2".into(),targets:vec![],ops:vec![Op::BQ062Investigation,Op::Forecast{player:PlayerRef::Actor,count:2}]},Mode{key:"lock".into(),label:"锁定目标角色或暗藏者，抓一张牌".into(),targets:vec![lock_slot()],ops:vec![Op::BQ062Lock,Op::Draw{player:PlayerRef::Actor,count:1,end:DeckEnd::Top}]},Mode{key:"contest".into(),label:"隐秘对抗：本人展示的命令牌+4".into(),targets:vec![],ops:vec![Op::MysticContest{actor_bonus:0}]}];with_abilities(vec![a])}
fn selected()->Vec<AbilitySpec>{let a=definition().abilities.remove(0);let mut all=vec![a.clone()];for m in &a.modes{let mut s=a.clone();s.targets=m.targets.clone();s.ops=m.ops.clone();s.modes.clear();all.push(s);}all}
fn op_related(o:&Op)->bool{matches!(o,Op::BQ062Investigation|Op::BQ062Lock)}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("bq062-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(op_related)}
pub(crate) fn frame_related(f:&ResolutionFrame)->bool{f.source.card.definition==ID||f.ability_key.starts_with("bq062-")||f.steps.iter().any(|s|op_related(&s.op))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!selected().iter().any(|s|same(s,a)){return Err("信息灌注须保留原三个标准行动模式".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("信息灌注完整定义不可删改或移植".into());}Ok(())}
pub(crate) fn validate_action(c:&Card,a:&Action)->RuleResult<()>{if c.definition!=ID{return Ok(());}if *a==(Action{card_id:a.card_id.clone(),..Action::new("asset")}){return Ok(());}if !matches!(a.option.as_deref(),Some("investigate"|"lock"|"contest"))||a.ability_id.as_deref().is_some_and(|k|k!=KEY)||*a!=(Action{card_id:a.card_id.clone(),ability_id:a.ability_id.clone(),option:a.option.clone(),target_id:if a.option.as_deref()==Some("lock"){a.target_id.clone()}else{None},..Action::new("play")}){return Err("信息灌注模式及目标载荷无效".into());}Ok(())}
impl Game{
 pub(crate) fn validate_bq062_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){return Ok(());}self.validate_resource_frame(f)?;let s=&f.source;let c=&s.card;let Some(a)=selected().into_iter().find(|a|a.modes.is_empty()&&same(&a.ops,&f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>()))else{return Err("信息灌注原模式程序损坏".into());};
 if c.definition!=ID||f.actor>=self.players.len()||c.owner>=self.players.len()||c.controller!=f.actor||c.face_down||!self.mystic_instance_number(&c.id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||f.ability_key!=KEY||f.cursor>f.steps.len()||f.chosen_region.is_some()||f.steps.iter().any(|s|s.context!=f.actor)||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor>0&&!matches!(f.guard,GuardState::Accepted)||f.targets.len()!=a.targets.len()||!matches!(f.already_paid.as_slice(),[PaidCost::Assets(ids)] if f.money_units(0)<=2&&ids.iter().collect::<BTreeSet<_>>().len()==ids.len()&&ids.iter().all(|id|id!=&c.id&&self.mystic_instance_number(id).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b))){return Err("信息灌注来源、支付或执行阶段损坏".into());}
 for(t,spec)in f.targets.iter().zip(a.targets){if !same(&t.spec,&spec)||t.region_instance.is_some()||!self.mystic_instance_valid(&t.id)||t.public.instance_id!=t.id||!t.public.valid||t.public.status!="valid"||t.public.invalid_reason.is_some(){return Err("信息灌注原地区目标损坏".into());}}self.mobility_immutable_identity(c)
 }
 pub(crate) fn validate_bq062_play(&self,i:&StackItem)->RuleResult<()>{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(frame_related){let f=i.frame.as_ref().ok_or("信息灌注实际事务缺帧")?;self.validate_bq062_frame(f)?;if f.source.card.definition!=ID||f.cursor!=0||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||i.target.as_deref()!=f.targets.first().map(|t|t.id.as_str())||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("信息灌注实际事务外壳损坏".into());}}Ok(())}

 fn bq062_options(&self,actor:usize)->Vec<ChoiceOption>{self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,x)|x.cards.iter().map(move|c|(r,c))).filter(|(_,c)|!c.face_down&&c.controller==actor&&(crate::tentacle::character(c)||c.owner==actor&&self.selected_core_card(c))).map(|(r,c)|self.option(c,actor,Some(r),None)).collect()}
 pub(crate) fn bq062_start(&mut self,f:ResolutionFrame)->RuleResult<()>{self.validate_bq062_frame(&f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ062Investigation){return Err("信息灌注调查须来自原模式".into());}if self.players[f.actor].eliminated{return Ok(());}let options=self.bq062_options(f.actor);if options.is_empty(){self.effects.push_front(Effect::Frame{frame:Box::new(f)});}else{self.choice(f.actor,"target",TITLE.into(),options,1,1,None,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ062Investigation});}Ok(())}
 pub(crate) fn bq062_finish(&mut self,f:ResolutionFrame,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.validate_bq062_frame(&f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ062Investigation)||seat!=f.actor||ids.len()!=1||*a!=(Action{choice_id:a.choice_id.clone(),selected:Some(ids.to_vec()),..Action::new("choose")})||!self.bq062_options(seat).iter().any(|o|o.id==ids[0]){return Err("信息灌注须选择一个当前本方核心或触手".into());}let c=self.board_mut(&ids[0]).ok_or("原角色离场")?;c.permanent_investigation_markers=c.permanent_investigation_markers.checked_add(1).ok_or("调查标志溢出")?;self.effects.push_front(Effect::Frame{frame:Box::new(f)});Ok(())}
 pub(crate) fn bq062_lock(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_bq062_frame(f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ062Lock){return Err("信息灌注锁定须来自原模式".into());}if self.valid_bound_target(f.actor,&f.source,&f.targets[0]){let c=self.board_mut(&f.targets[0].id).ok_or("原目标离场")?;c.lock_markers=c.lock_markers.checked_add(1).ok_or("锁定标志溢出")?;}Ok(())}
 pub(crate) fn validate_bq062_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();let mut check=|f:&ResolutionFrame|->RuleResult<()>{self.validate_bq062_frame(f)?;if frame_related(f)&&!seen.insert(f.frame_id.clone()){return Err("信息灌注同帧重复续体".into());}Ok(())};for i in &self.stack{self.validate_bq062_play(i)?;if let Some(f)=&i.frame{check(f)?;}}for e in &self.effects{match e{Effect::Frame{frame}=>check(frame)?,Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("信息灌注无触发声明".into()),_=>{}}}for state in self.mystic_states(){check(&state.frame)?;}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Frame{frame:f,choice}if frame_related(f)||matches!(choice,FrameChoice::BQ062Investigation)=>{self.validate_bq062_frame(f)?;if f.source.card.definition!=ID{return Err("信息灌注待选来源损坏".into());}if matches!(choice,FrameChoice::MysticCommit{..}|FrameChoice::MysticReward{..}){return Ok(());}check(f)?;let(options,kind,title,n,amount)=match choice{
 FrameChoice::BQ062Investigation if f.cursor==1&&matches!(f.steps[0].op,Op::BQ062Investigation)=>(self.bq062_options(f.actor),"target",TITLE.into(),1,None),
 FrameChoice::Forecast{seat}if *seat==f.actor&&f.cursor==2&&matches!(f.steps[0].op,Op::BQ062Investigation)=>{let options=self.players[*seat].deck.iter().take(2).map(|c|self.option(c,*seat,None,None)).collect::<Vec<_>>();let n=options.len();(options,"investigation",format!("预测 {n}"),n,Some(n as u32))},_=>return Err("信息灌注待选阶段损坏".into())};
 if options.is_empty()||p.seat!=f.actor||p.choice.player_id!=player_id(f.actor)||p.choice.kind!=kind||p.choice.title!=title||p.choice.min!=Some(n)||p.choice.max!=Some(n)||p.choice.amount!=amount||p.choice.allow_decline!=Some(false)||!p.choice.preview_cards.is_empty()||!same(&options,&p.choice.options){return Err("信息灌注真实单选或完整预测合同损坏".into());}},ChoiceResolution::Declare{declaration:d,..}if d.source.card.definition==ID||related(&d.ability)=>return Err("信息灌注不能伪装触发".into()),_=>{}}}Ok(())}
}
